INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20301, 'រូបមន្តដឺម័រ (de Moivre) កំណត់ថា \((\cos\varphi+i\sin\varphi)^n\) ស្មើ ៖', NULL, '["\\(n\\cos\\varphi+in\\sin\\varphi\\)", "\\(\\cos\\varphi^n+i\\sin\\varphi^n\\)", "\\(\\cos n\\varphi+i\\sin n\\varphi\\)", "\\(\\cos^n\\varphi+i\\sin^n\\varphi\\)"]', 2, NULL, 1, 'mcq', 'ស្វ័យគុណទី \(n\) ធ្វើឱ្យអាគុយម៉ង់គុណនឹង \(n\) ហើយម៉ូឌុល \(1\) នៅដដែល៖ \((\cos\varphi+i\sin\varphi)^n=\cos n\varphi+i\sin n\varphi\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20302, 'ចំនួនកុំផ្លិចមិនសូន្យ \(z\) មានឫសទី \(n\) ចំនួនប៉ុន្មាន ?', NULL, '["\\(n\\)", "\\(2\\)", "\\(n-1\\)", "\\(n+1\\)"]', 0, NULL, 1, 'mcq', 'រូបមន្ត \(w_k\) ជាមួយ \(k=0,1,\dots,n-1\) ឱ្យឫសផ្សេងគ្នា \(n\) ។ ពេល \(k=n\) ឫសនឹងចាប់ផ្ដើមដដែលវិញ។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20303, 'ពីរូបមន្តដឺម័រ ករណី \(n=2\) គេទាញបាន \(\cos2\varphi\) ស្មើ ៖', NULL, '["\\(2\\cos\\varphi\\)", "\\(\\cos^2\\varphi-\\sin^2\\varphi\\)", "\\(2\\sin\\varphi\\cos\\varphi\\)", "\\(\\cos^2\\varphi+\\sin^2\\varphi\\)"]', 1, NULL, 1, 'mcq', '\((\cos\varphi+i\sin\varphi)^2=(\cos^2\varphi-\sin^2\varphi)+2i\sin\varphi\cos\varphi\) ផ្ទឹមផ្នែកពិតនឹង \(\cos2\varphi\)។', 'អនុវត្តន៍ក្នុងត្រីកោណមាត្រ', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20304, 'បើ \(z=r(\cos\varphi+i\sin\varphi)\) នោះ \(|z^n|\) និង \(\arg z^n\) គឺ ៖', NULL, '["\\(r^n\\) និង \\(\\varphi^n\\)", "\\(r^n\\) និង \\(n\\varphi\\)", "\\(nr\\) និង \\(\\varphi^n\\)", "\\(nr\\) និង \\(n\\varphi\\)"]', 1, NULL, 1, 'mcq', '\(z^n=r^n(\cos n\varphi+i\sin n\varphi)\) ដូច្នេះ \(|z^n|=r^n\) និង \(\arg z^n=n\varphi\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20305, 'បើ \(z=r(\cos\varphi+i\sin\varphi)\) នោះឫសទី \(n\) នៃ \(z\) មានម៉ូឌុលស្មើ ៖', NULL, '["\\(\\sqrt[n]{r}\\)", "\\(r^n\\)", "\\(\\dfrac rn\\)", "\\(nr\\)"]', 0, NULL, 1, 'mcq', 'ពី \(s^n=r\) និង \(s>0\) គេបាន \(s=\sqrt[n]{r}\)។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20306, 'បើ \(z=\cos\dfrac\pi6+i\sin\dfrac\pi6\) នោះ \(z^{12}\) ស្មើ ៖', NULL, '["\\(0\\)", "\\(i\\)", "\\(1\\)", "\\(-1\\)"]', 2, NULL, 1, 'mcq', '\(z^{12}=\cos\left(12\cdot\dfrac\pi6\right)+i\sin\left(12\cdot\dfrac\pi6\right)=\cos2\pi+i\sin2\pi=1\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-5401285281.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20307, 'ក្នុងរូប ចំណុច \(M_0,\ M_1,\dots,\ M_5\) ជារូបភាពនៃឫសទី \(6\) នៃ \(1\) លើរង្វង់ត្រីកោណមាត្រ។ មុំរវាង \(\overrightarrow{OM_k}\) និង \(\overrightarrow{OM_{k+1}}\) (ជាប់គ្នា) ស្មើ ៖', 'g12sc-5401285281.svg', '["\\(\\dfrac{\\pi}{2}\\)", "\\(\\dfrac{\\pi}{3}\\)", "\\(\\dfrac{\\pi}{6}\\)", "\\(\\dfrac{2\\pi}{3}\\)"]', 1, NULL, 1, 'mcq', 'ឫសទី \(6\) មានអាគុយម៉ង់ \(\dfrac{2k\pi}{6}=\dfrac{k\pi}{3}\) ដូច្នេះមុំរវាងឫសជាប់គ្នាស្មើ \(\dfrac{2\pi}{6}=\dfrac\pi3\) ហើយឫសជាកំពូលនៃឆកោននិយ័ត។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20308, 'គណនា \((1+i)^8\) ៖', NULL, '["\\(8\\)", "\\(-16\\)", "\\(16i\\)", "\\(16\\)"]', 3, NULL, 1, 'mcq', '\((1+i)^2=2i\) ដូច្នេះ \((1+i)^8=(2i)^4=16i^4=16\) (ឬ \((\sqrt2)^8(\cos2\pi+i\sin2\pi)=16\))។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20309, 'ចំនួនមួយណាខាងក្រោមជាឫសគូបនៃ \(8\) ?', NULL, '["\\(-1 + \\sqrt{3}i\\)", "\\(1 + i\\)", "\\(1 + \\sqrt{3}i\\)", "\\(2i\\)"]', 0, NULL, 1, 'mcq', '\(-1+i\sqrt3=2\left(\cos\tfrac{2\pi}{3}+i\sin\tfrac{2\pi}{3}\right)\) ដូច្នេះ \((-1+i\sqrt3)^3=8(\cos2\pi+i\sin2\pi)=8\)។ \((1+i\sqrt3)^3=-8\) និង \((2i)^3=-8i\) មិនមែន។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20310, 'គណនា \((-1+i)^4\) ៖', NULL, '["\\(-4i\\)", "\\(4\\)", "\\(16\\)", "\\(-4\\)"]', 3, NULL, 1, 'mcq', '\((-1+i)^2=1-2i+i^2=-2i\) ដូច្នេះ \((-1+i)^4=(-2i)^2=4i^2=-4\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20311, 'គណនា \((\sqrt3+i)^6\) ៖', NULL, '["\\(-64i\\)", "\\(64i\\)", "\\(64\\)", "\\(-64\\)"]', 3, NULL, 2, 'mcq', '\(\sqrt3+i=2\left(\cos\tfrac\pi6+i\sin\tfrac\pi6\right)\) ដូច្នេះ \((\sqrt3+i)^6=2^6(\cos\pi+i\sin\pi)=-64\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20312, 'រូបមន្តមួយណាត្រឹមត្រូវសម្រាប់ \(\cos3\varphi\) ?', NULL, '["\\(4\\cos^3\\varphi-3\\cos\\varphi\\)", "\\(\\cos^3\\varphi+3\\cos\\varphi\\sin^2\\varphi\\)", "\\(3\\cos^2\\varphi\\sin\\varphi-\\sin^3\\varphi\\)", "\\(3\\cos\\varphi-4\\cos^3\\varphi\\)"]', 0, NULL, 2, 'mcq', 'ផ្នែកពិតនៃ \((\cos\varphi+i\sin\varphi)^3\) គឺ \(\cos^3\varphi-3\cos\varphi\sin^2\varphi=4\cos^3\varphi-3\cos\varphi\) (ប្រើ \(\sin^2\varphi=1-\cos^2\varphi\))។', 'អនុវត្តន៍ក្នុងត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20313, 'ឫសការ៉េនៃ \(z=9\left(\cos\dfrac\pi4+i\sin\dfrac\pi4\right)\) គឺ ៖', NULL, '["\\(\\pm\\sqrt3\\left(\\cos\\dfrac\\pi8+i\\sin\\dfrac\\pi8\\right)\\)", "\\(\\pm3\\left(\\cos\\dfrac\\pi8+i\\sin\\dfrac\\pi8\\right)\\)", "\\(\\pm3\\left(\\cos\\dfrac\\pi4+i\\sin\\dfrac\\pi4\\right)\\)", "\\(\\pm9\\left(\\cos\\dfrac\\pi8+i\\sin\\dfrac\\pi8\\right)\\)"]', 1, NULL, 2, 'mcq', 'ម៉ូឌុលឫសការ៉េ \(\sqrt9=3\) អាគុយម៉ង់ \(\dfrac{\pi/4+2k\pi}{2}\) គឺ \(\dfrac\pi8\) ឬ \(\dfrac{9\pi}{8}\) ពោលគឺឫសពីរជាចំនួនផ្ទុយគ្នា \(\pm3(\cos\tfrac\pi8+i\sin\tfrac\pi8)\)។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20314, 'ចំនួនមួយណាខាងក្រោមជាឫសនៃសមីការ \(z^6+64=0\) ?', NULL, '["\\(\\sqrt3\\)", "\\(1+i\\)", "\\(2\\)", "\\(2i\\)"]', 3, NULL, 2, 'mcq', '\((2i)^6=2^6i^6=64\cdot(-1)=-64\) ដូច្នេះ \((2i)^6+64=0\)។ \(2^6=64\) និង \((\sqrt3)^6=27\) ហើយ \((1+i)^6=(2i)^3=-8i\) មិនស្មើ \(-64\)។', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20315, 'គណនា \((1-i)^{10}\) ៖', NULL, '["\\(-32\\)", "\\(32\\)", "\\(-32i\\)", "\\(32i\\)"]', 2, NULL, 2, 'mcq', '\(1-i=\sqrt2\left[\cos\left(-\tfrac\pi4\right)+i\sin\left(-\tfrac\pi4\right)\right]\) ដូច្នេះ \((1-i)^{10}=2^5\left[\cos\left(-\tfrac{5\pi}2\right)+i\sin\left(-\tfrac{5\pi}2\right)\right]=32(-i)=-32i\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20316, 'រូបមន្តមួយណាត្រឹមត្រូវសម្រាប់ \(\sin3\varphi\) ?', NULL, '["\\(\\sin^3\\varphi-3\\cos^2\\varphi\\sin\\varphi\\)", "\\(4\\sin^3\\varphi-3\\sin\\varphi\\)", "\\(3\\sin\\varphi-4\\sin^3\\varphi\\)", "\\(3\\sin\\varphi+4\\sin^3\\varphi\\)"]', 2, NULL, 2, 'mcq', 'ផ្នែកនិមិត្តនៃ \((\cos\varphi+i\sin\varphi)^3\) គឺ \(3\cos^2\varphi\sin\varphi-\sin^3\varphi=3\sin\varphi-4\sin^3\varphi\)។', 'អនុវត្តន៍ក្នុងត្រីកោណមាត្រ', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20317, 'ឫសទី \(4\) នៃ \(16\) ក្នុងទម្រង់ \(a+bi\) គឺ ៖', NULL, '["\\(4,\\ 4i,\\ -4,\\ -4i\\)", "\\(\\sqrt{2} + \\sqrt{2}i,\\ - \\sqrt{2} + \\sqrt{2}i,\\ - \\sqrt{2} - \\sqrt{2}i,\\ \\sqrt{2} - \\sqrt{2}i\\)", "\\(1,\\ i,\\ -1,\\ -i\\)", "\\(2,\\ 2i,\\ -2,\\ -2i\\)"]', 3, NULL, 2, 'mcq', '\(16=16(\cos0+i\sin0)\) ដូច្នេះ \(w_k=2\left(\cos\tfrac{k\pi}{2}+i\sin\tfrac{k\pi}{2}\right)\) ដែល \(k=0,1,2,3\) គឺ \(2,\ 2i,\ -2,\ -2i\)។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20318, 'ដោះស្រាយសមីការ \((z-2)^3=1\) ៖', NULL, '["\\(2,\\ 2+\\dfrac{\\sqrt3}{2}i,\\ 2-\\dfrac{\\sqrt3}{2}i\\)", "\\(-1,\\ \\dfrac12+\\dfrac{\\sqrt3}{2}i,\\ \\dfrac12-\\dfrac{\\sqrt3}{2}i\\)", "\\(1,\\ -\\dfrac12+\\dfrac{\\sqrt3}{2}i,\\ -\\dfrac12-\\dfrac{\\sqrt3}{2}i\\)", "\\(3,\\ \\dfrac32+\\dfrac{\\sqrt3}{2}i,\\ \\dfrac32-\\dfrac{\\sqrt3}{2}i\\)"]', 3, NULL, 2, 'mcq', '\(z-2\) ជាឫសគូបនៃ \(1\) គឺ \(1,\ -\tfrac12\pm\tfrac{\sqrt3}2i\) ហើយ \(z=w+2\) បាន \(3,\ \tfrac32\pm\tfrac{\sqrt3}{2}i\)។', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20319, 'សរសេរ \((-\sqrt3+i)^{13}\) ជាទម្រង់ \(a+bi\) ៖', NULL, '["\\(4\\,096 \\sqrt{3} - 4\\,096i\\)", "\\(- 13 \\sqrt{3} + 13i\\)", "\\(- 4\\,096 \\sqrt{3} + 4\\,096i\\)", "\\(- 4\\,096 \\sqrt{3} - 4\\,096i\\)"]', 2, NULL, 2, 'mcq', '\(-\sqrt3+i=2\left(\cos\tfrac{5\pi}6+i\sin\tfrac{5\pi}6\right)\) ដូច្នេះ \((-\sqrt3+i)^{13}=2^{13}\left(\cos\tfrac{65\pi}6+i\sin\tfrac{65\pi}6\right)=2^{13}\left(\cos\tfrac{5\pi}6+i\sin\tfrac{5\pi}6\right)=-2^{12}\sqrt3+2^{12}i\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-17fb257616.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20320, 'ក្នុងរូប ចំណុច \(M_0,\dots,M_4\) ជារូបភាពនៃឫសទី \(5\) នៃចំនួនកុំផ្លិចមួយ ដែលស្ថិតលើរង្វង់ដូចគ្នា។ មុំ \(\widehat{M_0OM_1}\) ស្មើ ៖', 'g12sc-17fb257616.svg', '["\\(\\dfrac{2\\pi}{5}\\)", "\\(\\dfrac{\\pi}{5}\\)", "\\(\\dfrac{4\\pi}{5}\\)", "\\(\\dfrac{\\pi}{3}\\)"]', 0, NULL, 2, 'mcq', 'ឫសទី \(5\) មានអាគុយម៉ង់ដាច់ពីគ្នា \(\dfrac{2\pi}{5}\) (\(=72^\circ\)) ដូច្នេះកំពូលបង្កើតបានជាបញ្ចកោណនិយ័ត។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20321, 'ផលបូកនៃឫសគូបទាំងបីនៃ \(1\) ស្មើ ៖', NULL, '["\\(3\\)", "\\(1\\)", "\\(0\\)", "\\(-1\\)"]', 2, NULL, 2, 'mcq', 'ឫសគឺ \(1\) និង \(-\tfrac12\pm\tfrac{\sqrt3}{2}i\) ដូច្នេះផលបូក \(1+\left(-\tfrac12+\tfrac{\sqrt3}2i\right)+\left(-\tfrac12-\tfrac{\sqrt3}2i\right)=0\)។ (ក្នុងសមីការ \(z^3-1=0\) មេគុណ \(z^2\) ស្មើសូន្យ។)', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20322, 'គណនា \(\left(\dfrac{1+i}{1-i}\right)^{2n}\) ដែល \(n\) ជាចំនួនគត់វិជ្ជមាន ៖', NULL, '["\\((-1)^n\\)", "\\(-1\\)", "\\(i^n\\)", "\\(1\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{1+i}{1-i}=i\) ដូច្នេះ \(i^{2n}=(i^2)^n=(-1)^n\) (ស្មើ \(1\) បើ \(n\) គូ ហើយ \(-1\) បើ \(n\) សេស)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20323, 'ឫសទី \(4\) នៃ \(z=-8-8\sqrt3\,i\) មានអាគុយម៉ង់ \(\dfrac{4\pi/3+2k\pi}{4}\)។ អាគុយម៉ង់នៃឫស \(w_1\) (\(k=1\)) ស្មើ ៖', NULL, '["\\(\\dfrac{11\\pi}{6}\\)", "\\(\\dfrac{5\\pi}{6}\\)", "\\(\\dfrac{\\pi}{3}\\)", "\\(\\dfrac{2\\pi}{3}\\)"]', 1, NULL, 2, 'mcq', '\(\dfrac{\tfrac{4\pi}{3}+2\pi}{4}=\dfrac{\tfrac{10\pi}{3}}{4}=\dfrac{5\pi}{6}\) (ចំណែក \(k=0\) ឱ្យ \(\tfrac\pi3\) ហើយ \(k=3\) ឱ្យ \(\tfrac{11\pi}{6}\))។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20324, 'ផលគុណនៃឫសគូបទាំងបីនៃ \(1\) ស្មើ ៖', NULL, '["\\(-1\\)", "\\(1\\)", "\\(0\\)", "\\(3\\)"]', 1, NULL, 2, 'mcq', '\(1\cdot\left(-\tfrac12+\tfrac{\sqrt3}2i\right)\left(-\tfrac12-\tfrac{\sqrt3}2i\right)=\tfrac14+\tfrac34=1\)។', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'medium', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20325, 'គណនា \(u=(1+i\sqrt3)^5+(1-i\sqrt3)^5\) ៖', NULL, '["\\(64\\)", "\\(32i\\)", "\\(16\\)", "\\(32\\)"]', 3, NULL, 3, 'mcq', '\(1+i\sqrt3=2\left(\cos\tfrac\pi3+i\sin\tfrac\pi3\right)\) ដូច្នេះ \((1+i\sqrt3)^5=32\left(\cos\tfrac{5\pi}3+i\sin\tfrac{5\pi}3\right)=16-16\sqrt3\,i\) ហើយ \((1-i\sqrt3)^5\) ជាចំនួនឆ្លាស់ \(16+16\sqrt3\,i\) ដូច្នេះ \(u=32\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20326, 'ចំនួន \(z_0=\sqrt2(1+i)\) ជាឫសមួយនៃសមីការមួយណាខាងក្រោម ?', NULL, '["\\(z^4+16=0\\)", "\\(z^2-4=0\\)", "\\(z^4-16=0\\)", "\\(z^4+4=0\\)"]', 0, NULL, 3, 'mcq', '\(z_0=2\left(\cos\tfrac\pi4+i\sin\tfrac\pi4\right)\) ដូច្នេះ \(z_0^4=16(\cos\pi+i\sin\pi)=-16\) ពោលគឺ \(z_0^4+16=0\)។ (សមីការ \(z^4-16=0\) មានឫស \(\pm2,\pm2i\) ហើយ \(z_0^2=4i\ne4\))។', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'hard', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-5b88758598.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20327, 'ក្នុងរូប ចំណុច \(M_0,\ M_1,\ M_2,\ M_3\) ជារូបភាពនៃឫសទី \(4\) នៃចំនួនកុំផ្លិច \(z\)។ ចំណុច \(M_0\) មានម៉ូឌុល \(2\) និងអាគុយម៉ង់ \(\dfrac\pi3\)។ ចំនួន \(z\) ស្មើ ៖', 'g12sc-5b88758598.svg', '["\\(16\\)", "\\(-8 + 8 \\sqrt{3}i\\)", "\\(-8 - 8 \\sqrt{3}i\\)", "\\(8 - 8 \\sqrt{3}i\\)"]', 2, NULL, 3, 'mcq', 'ឫសមួយ \(w_0=2\left(\cos\tfrac\pi3+i\sin\tfrac\pi3\right)\) ដូច្នេះ \(z=w_0^4=16\left(\cos\tfrac{4\pi}3+i\sin\tfrac{4\pi}3\right)=16\left(-\tfrac12-\tfrac{\sqrt3}{2}i\right)=-8-8\sqrt3\,i\) (ឫសទាំងបួនស្មើគ្នា \(\tfrac\pi2\) រវាងគ្នា)។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20328, 'បើ \(z=\cos\dfrac\pi6+i\sin\dfrac\pi6\) នោះ \(S=1+z+z^2+z^3+\dots+z^{11}\) ស្មើ ៖', NULL, '["\\(-1\\)", "\\(0\\)", "\\(1\\)", "\\(12\\)"]', 1, NULL, 3, 'mcq', '\(z^{12}=\cos2\pi+i\sin2\pi=1\) ហើយ \(z\ne1\) ដូច្នេះ \(S=\dfrac{z^{12}-1}{z-1}=0\) (ផលបូកស្វ៊ីតធរណីមាត្រ)។', 'អនុវត្តន៍ក្នុងត្រីកោណមាត្រ', 'hard', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20329, 'សិស្សម្នាក់សរសេរថា \((\cos\varphi+i\sin\varphi)^n=\cos^n\varphi+i\sin^n\varphi\)។ ឃ្លាមួយណាវាយតម្លៃបានត្រឹមត្រូវ ?', NULL, '["ខុស ឧ. \\(\\varphi=\\tfrac\\pi4,\\ n=2\\) ៖ ខាងឆ្វេងស្មើ \\(i\\) តែខាងស្ដាំស្មើ \\(\\tfrac12+\\tfrac12i\\)", "ត្រឹមត្រូវតែពេល \\(n\\) ជាចំនួនគូប៉ុណ្ណោះ", "ខុស ព្រោះត្រូវជា \\(n\\cos\\varphi+in\\sin\\varphi\\) ពោលគឺគុណនឹង \\(n\\)", "ត្រឹមត្រូវ ព្រោះស្វ័យគុណអនុវត្តលើ \\(\\cos\\) និង \\(\\sin\\) ដោយឡែកពីគ្នា"]', 0, NULL, 3, 'mcq', 'រូបមន្តត្រឹមត្រូវគឺ \(\cos n\varphi+i\sin n\varphi\) (គុណអាគុយម៉ង់នឹង \(n\))។ ជាមួយ \(\varphi=\tfrac\pi4,\ n=2\) ៖ \((\cos\tfrac\pi4+i\sin\tfrac\pi4)^2=\cos\tfrac\pi2+i\sin\tfrac\pi2=i\) តែ \(\cos^2\tfrac\pi4+i\sin^2\tfrac\pi4=\tfrac12+\tfrac12i\) ខុសគ្នា។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20330, 'សមីការ \(z^6+2z^3+1=0\) មានឫសខុសៗគ្នាប៉ុន្មានក្នុង \(\mathbb{C}\) ?', NULL, '["2", "6", "3", "1"]', 2, NULL, 3, 'mcq', '\(z^6+2z^3+1=(z^3+1)^2\) ដូច្នេះសមីការសមមូល \(z^3=-1\) ដែលមានឫសខុសគ្នា \(3\) គឺ \(\tfrac12\pm\tfrac{\sqrt3}2i\) និង \(-1\) (ឫសនីមួយៗជាឫសទ្វេ មិនមែនមាន \(6\) ឫសខុសគ្នាទេ)។', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'hard', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20331, 'គេដឹងថា \(\dfrac{1+\sin\varphi+i\cos\varphi}{1+\sin\varphi-i\cos\varphi}=\cos\left(\dfrac\pi2-\varphi\right)+i\sin\left(\dfrac\pi2-\varphi\right)\)។ ស្វ័យគុណទី \(n\) នៃប្រភាគនេះស្មើ ៖', NULL, '["\\(\\cos n\\varphi+i\\sin n\\varphi\\)", "\\(\\cos\\left[n\\left(\\dfrac\\pi2-\\varphi\\right)\\right]+i\\sin\\left[n\\left(\\dfrac\\pi2-\\varphi\\right)\\right]\\)", "\\(\\cos\\left[\\dfrac{1}{n}\\left(\\dfrac\\pi2-\\varphi\\right)\\right]+i\\sin\\left[\\dfrac{1}{n}\\left(\\dfrac\\pi2-\\varphi\\right)\\right]\\)", "\\(\\cos\\left[n\\left(\\dfrac\\pi2+\\varphi\\right)\\right]+i\\sin\\left[n\\left(\\dfrac\\pi2+\\varphi\\right)\\right]\\)"]', 1, NULL, 3, 'mcq', 'ប្រភាគមានម៉ូឌុល \(1\) និងអាគុយម៉ង់ \(\tfrac\pi2-\varphi\) ដូច្នេះតាមរូបមន្តដឺម័រ អាគុយម៉ង់ត្រូវគុណនឹង \(n\) ៖ \(\cos[n(\tfrac\pi2-\varphi)]+i\sin[n(\tfrac\pi2-\varphi)]\)។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-bc4a70a3ea.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20332, 'កង់ទេសចរណ៍កាំ \(10\ \text{m}\) មាន ១២ កាប៊ីនស្ថិតស្មើគ្នាលើរង្វង់ ដូចក្នុងរូប (ជុំវិញផ្ចិត \(O\) ជាគល់នៃប្លង់កុំផ្លិច)។ កាប៊ីនលេខ \(0\) នៅត្រង់ \(10\) ។ កាប៊ីនលេខ \(k\) ស្ថិតត្រង់ \(10\left(\cos\tfrac{k\pi}6+i\sin\tfrac{k\pi}6\right)\)។ កាប៊ីនលេខ \(3\) ស្ថិតត្រង់ចំនួនកុំផ្លិច ៖', 'g12sc-bc4a70a3ea.svg', '["\\(10\\)", "\\(-10i\\)", "\\(10i\\)", "\\(5\\sqrt3+5i\\)"]', 2, NULL, 3, 'mcq', 'ជាមួយ \(k=3\) ៖ \(10\left(\cos\tfrac\pi2+i\sin\tfrac\pi2\right)=10i\) (ចុងកំពូលនៃកង់)។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-adcf03c233.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20333, 'ស្ថានីយ៍ផ្ទេរសញ្ញាបីដាក់ស្មើគ្នាលើរង្វង់កាំ \(6\ \text{km}\) ជុំវិញប៉មមួយ ដូចក្នុងរូប។ ស្ថានីយ៍ទី ១ នៅត្រង់ \(6\) (ជាឫសគូបនៃ \(216\))។ ចម្ងាយរវាងស្ថានីយ៍ណាមួយពីរគឺ ៖', 'g12sc-adcf03c233.svg', '["\\(6\\ \\text{km}\\)", "\\(6\\sqrt3\\ \\text{km}\\)", "\\(3\\sqrt3\\ \\text{km}\\)", "\\(12\\ \\text{km}\\)"]', 1, NULL, 3, 'mcq', 'ឫសគូបនៃ \(216\) គឺ \(6,\ -3+3\sqrt3\,i,\ -3-3\sqrt3\,i\)។ \(|(-3+3\sqrt3\,i)-6|=|-9+3\sqrt3\,i|=\sqrt{81+27}=\sqrt{108}=6\sqrt3\) ដូចគ្នាចំពោះគ្រប់គូ (ត្រីកោណសមមាត្រ)។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20334, 'មនុស្សយន្តបង្វិលទិសខ្លួនច្រាសទ្រនិចនាឡិកា \(15^\circ\) (\(=\dfrac\pi{12}\)) រាល់ពេលទទួលបញ្ជា។ ទិសបច្ចុប្បន្នតាងដោយ \(z_0=1\) ហើយក្រោយបញ្ជា \(n\) ដងទិសគឺ \(\left(\cos\tfrac\pi{12}+i\sin\tfrac\pi{12}\right)^n\)។ ក្រោយបញ្ជាប៉ុន្មានដង ទើបមនុស្សយន្តត្រលប់មកទិសដើមជាលើកដំបូង ?', NULL, '["24 ដង", "6 ដង", "12 ដង", "48 ដង"]', 0, NULL, 3, 'mcq', 'ត្រូវការ \(\left(\cos\tfrac\pi{12}+i\sin\tfrac\pi{12}\right)^n=\cos\tfrac{n\pi}{12}+i\sin\tfrac{n\pi}{12}=1\) គឺ \(\tfrac{n\pi}{12}=2\pi\) ដូច្នេះ \(n=24\) (ក្រោយ 12 ដងត្រូវបានទិសផ្ទុយ \(-1\))។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-ff7a3f61a9.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20335, 'បង្គោលភ្លើងប្រាំស្ថិតស្មើគ្នាជុំវិញសួនរង្វង់កាំ \(2\ \text{m}\) ជាឫសទី \(5\) នៃ \(32\) ដូចក្នុងរូប ដែលបង្គោល \(L_0\) នៅត្រង់ \(2\)។ បង្គោល \(L_k\) មានអាគុយម៉ង់ \(\tfrac{2k\pi}{5}\)។ អាគុយម៉ង់នៃបង្គោល \(L_2\) ស្មើ ៖', 'g12sc-ff7a3f61a9.svg', '["\\(\\dfrac{2\\pi}{5}\\)", "\\(\\dfrac{6\\pi}{5}\\)", "\\(\\dfrac{8\\pi}{5}\\)", "\\(\\dfrac{4\\pi}{5}\\)"]', 3, NULL, 3, 'mcq', '\(32=32(\cos0+i\sin0)\) ដូច្នេះ \(w_k=2\left(\cos\tfrac{2k\pi}5+i\sin\tfrac{2k\pi}5\right)\)។ ជាមួយ \(k=2\) ៖ អាគុយម៉ង់ \(\tfrac{4\pi}{5}\)។', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20336, 'ការឆ្លើយតបនៃដំណាក់កាលតម្រងមួយតាងដោយ \(G=\sqrt2\left(\cos\dfrac\pi{12}+i\sin\dfrac\pi{12}\right)\)។ ដំណាក់កាលដូចគ្នាប្រាំមួយតភ្ជាប់គ្នា ការឆ្លើយតបសរុបគឺ \(G^6\) ស្មើ ៖', NULL, '["\\(-8\\)", "\\(64i\\)", "\\(8\\)", "\\(8i\\)"]', 3, NULL, 3, 'mcq', '\(G^6=(\sqrt2)^6\left(\cos\tfrac{6\pi}{12}+i\sin\tfrac{6\pi}{12}\right)=8\left(\cos\tfrac\pi2+i\sin\tfrac\pi2\right)=8i\) (អំព្លីទុត \(8\) ផាស \(90^\circ\))។', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20337, 'គណនា \((1+i)^{12}\) ដោយប្រើទម្រង់ត្រីកោណមាត្រ។', NULL, '[]', 0, NULL, 5, 'writing', 'ម៉ូឌុល និងអាគុយម៉ង់ ៖ \(1+i=\sqrt2\left(\cos\tfrac\pi4+i\sin\tfrac\pi4\right)\) (2 ពិន្ទុ)
រូបមន្តដឺម័រ ៖ \((1+i)^{12}=(\sqrt2)^{12}\left(\cos\tfrac{12\pi}{4}+i\sin\tfrac{12\pi}{4}\right)=64(\cos3\pi+i\sin3\pi)\) (2 ពិន្ទុ)
ដូច្នេះ \((1+i)^{12}=64\times(-1)=-64\) (1 ពិន្ទុ)', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'easy', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20338, 'សរសេរ \((-\sqrt3+i)^{13}\) ជាទម្រង់ពីជគណិត \(a+bi\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ម៉ូឌុល ៖ \(r=\sqrt{(-\sqrt3)^2+1^2}=2\) (1 ពិន្ទុ)
អាគុយម៉ង់ ៖ \(\cos\varphi=-\dfrac{\sqrt3}2\) និង \(\sin\varphi=\dfrac12\) ដូច្នេះ \(\varphi=\dfrac{5\pi}6\) គឺ \(-\sqrt3+i=2\left(\cos\tfrac{5\pi}6+i\sin\tfrac{5\pi}6\right)\) (1 ពិន្ទុ)
រូបមន្តដឺម័រ ៖ \((-\sqrt3+i)^{13}=2^{13}\left(\cos\tfrac{65\pi}6+i\sin\tfrac{65\pi}6\right)\) (1 ពិន្ទុ)
កាត់ \(2\pi\) ចេញ ៖ \(\tfrac{65\pi}{6}=10\pi+\tfrac{5\pi}6\) ដូច្នេះ \(=2^{13}\left(\cos\tfrac{5\pi}6+i\sin\tfrac{5\pi}6\right)\) (1 ពិន្ទុ)
ទម្រង់ពីជគណិត ៖ \(=2^{13}\left(-\tfrac{\sqrt3}2+\tfrac12i\right)=-2^{12}\sqrt3+2^{12}i\) (1 ពិន្ទុ)', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'medium', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
