INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20339, 'គណនាឫសទី \(5\) នៃចំនួនកុំផ្លិច \(z=-1+i\) រួចតាងចំណុចរូបភាពនៃឫសទាំងនោះលើរង្វង់ ដូចក្នុងរូប។', 'g12sc-7963227b05.svg', '[]', 0, NULL, 5, 'writing', 'ម៉ូឌុល និងអាគុយម៉ង់ ៖ \(r=\sqrt2\) និង \(\varphi=\tfrac{3\pi}4\) គឺ \(z=\sqrt2\left(\cos\tfrac{3\pi}4+i\sin\tfrac{3\pi}4\right)\) (1 ពិន្ទុ)
រូបមន្តឫស ៖ \(w_k=2^{\frac1{10}}\left[\cos\tfrac{\frac{3\pi}4+2k\pi}{5}+i\sin\tfrac{\frac{3\pi}4+2k\pi}{5}\right]\) ដែល \(k=0,1,2,3,4\) (1 ពិន្ទុ)
សម្រួលអាគុយម៉ង់ ៖ \(\tfrac{3\pi+8k\pi}{20}\) ដូច្នេះ \(w_k=2^{\frac1{10}}\left[\cos\tfrac{3\pi+8k\pi}{20}+i\sin\tfrac{3\pi+8k\pi}{20}\right]\) (1 ពិន្ទុ)
តម្លៃអាគុយម៉ង់ ៖ \(\tfrac{3\pi}{20},\ \tfrac{11\pi}{20},\ \tfrac{19\pi}{20},\ \tfrac{27\pi}{20},\ \tfrac{35\pi}{20}\) សម្រាប់ \(k=0,\dots,4\) (1 ពិន្ទុ)
រូបភាព ៖ ឫសទាំង ៥ ស្ថិតលើរង្វង់កាំ \(2^{1/10}\approx1{,}07\) ហើយជាកំពូលនៃបញ្ចកោណនិយ័ត (អាគុយម៉ង់ដាច់ពីគ្នា \(\tfrac{2\pi}5\))។ (1 ពិន្ទុ)', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'medium', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20340, 'ដោះស្រាយសមីការ \(z^6+64=0\) ក្នុង \(\mathbb{C}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សមីការសមមូល \(z^6=-64\) គឺ \(z\) ជាឫសទី \(6\) នៃ \(-64\) (1 ពិន្ទុ)
ទម្រង់ត្រីកោណមាត្រ ៖ \(-64=64(\cos\pi+i\sin\pi)\) (1 ពិន្ទុ)
រូបមន្តឫស ៖ \(w_k=2\left(\cos\tfrac{\pi+2k\pi}6+i\sin\tfrac{\pi+2k\pi}6\right)\) ដែល \(k=0,\dots,5\) (1 ពិន្ទុ)
គណនា ៖ \(w_0=\sqrt3+i\), \(w_1=2i\), \(w_2=-\sqrt3+i\) (1 ពិន្ទុ)
\(w_3=-\sqrt3-i\), \(w_4=-2i\), \(w_5=\sqrt3-i\) (កំពូលនៃឆកោននិយ័តកាំ \(2\))។ (1 ពិន្ទុ)', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'medium', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20341, 'គណនា \(z=\left(\dfrac{1+i}{1-i}\right)^{2n}\) ដែល \(n\) ជាចំនួនគត់វិជ្ជមាន ហើយបញ្ជាក់តម្លៃនៃ \(z\) ក្នុងករណី \(n\) គូ និង \(n\) សេស។', NULL, '[]', 0, NULL, 5, 'writing', 'សម្រួលប្រភាគ ៖ \(\dfrac{1+i}{1-i}=\dfrac{(1+i)(1+i)}{(1-i)(1+i)}=\dfrac{2i}{2}=i\) (1 ពិន្ទុ)
ទម្រង់ត្រីកោណមាត្រ ៖ \(i=\cos\tfrac\pi2+i\sin\tfrac\pi2\) (ម៉ូឌុល \(1\)) (1 ពិន្ទុ)
រូបមន្តដឺម័រ ៖ \(z=i^{2n}=\cos(n\pi)+i\sin(n\pi)\) (1 ពិន្ទុ)
ដូច្នេះ \(z=(\cos\pi+i\sin\pi)^n=(-1)^n\) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ \(z=1\) បើ \(n\) គូ ហើយ \(z=-1\) បើ \(n\) សេស។ (ផ្ទៀងផ្ទាត់ ៖ \(i^{2n}=(i^2)^n=(-1)^n\))។ (1 ពិន្ទុ)', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'medium', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20342, 'ស្រាយបញ្ជាក់សមភាព \(\left(\dfrac{1+\sin\varphi+i\cos\varphi}{1+\sin\varphi-i\cos\varphi}\right)^n=\cos\left[n\left(\dfrac\pi2-\varphi\right)\right]+i\sin\left[n\left(\dfrac\pi2-\varphi\right)\right]\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គុណភាគយក និងភាគបែងនឹង \(1+\sin\varphi+i\cos\varphi\) ៖ \(\dfrac{(1+\sin\varphi+i\cos\varphi)^2}{(1+\sin\varphi)^2-(i\cos\varphi)^2}\) (1 ពិន្ទុ)
ភាគបែង ៖ \((1+\sin\varphi)^2+\cos^2\varphi=2(1+\sin\varphi)\) (1 ពិន្ទុ)
ភាគយក ៖ \(1+\sin^2\varphi-\cos^2\varphi+2\sin\varphi+2i\cos\varphi(1+\sin\varphi)=2\sin\varphi(1+\sin\varphi)+2i\cos\varphi(1+\sin\varphi)\) (1 ពិន្ទុ)
ចែក ៖ ប្រភាគ \(=\sin\varphi+i\cos\varphi=\cos\left(\tfrac\pi2-\varphi\right)+i\sin\left(\tfrac\pi2-\varphi\right)\) (1 ពិន្ទុ)
រូបមន្តដឺម័រ ៖ ស្វ័យគុណទី \(n\) ឱ្យ \(\cos\left[n\left(\tfrac\pi2-\varphi\right)\right]+i\sin\left[n\left(\tfrac\pi2-\varphi\right)\right]\) ជាសមភាពដែលត្រូវស្រាយ។ (1 ពិន្ទុ)', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'hard', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20343, 'ក. ដោយប្រើរូបមន្តដឺម័រ \(n=3\) បង្ហាញថា \(\cos3\varphi=4\cos^3\varphi-3\cos\varphi\)។ ខ. ទាញថា \(x=\cos\dfrac\pi9\) ជាឫសនៃសមីការ \(8x^3-6x-1=0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្លាត ៖ \((\cos\varphi+i\sin\varphi)^3=\cos^3\varphi+3i\cos^2\varphi\sin\varphi-3\cos\varphi\sin^2\varphi-i\sin^3\varphi\) (1 ពិន្ទុ)
ផ្នែកពិត ៖ \(\cos^3\varphi-3\cos\varphi\sin^2\varphi\) (1 ពិន្ទុ)
ប្រើ \(\sin^2\varphi=1-\cos^2\varphi\) និងរូបមន្តដឺម័រ \((\cdots)^3=\cos3\varphi+i\sin3\varphi\) បាន \(\cos3\varphi=4\cos^3\varphi-3\cos\varphi\) (1 ពិន្ទុ)
ជំនួស \(\varphi=\tfrac\pi9\) ៖ \(\cos\tfrac\pi3=4x^3-3x\) ដែល \(x=\cos\tfrac\pi9\) (1 ពិន្ទុ)
ដោយ \(\cos\tfrac\pi3=\tfrac12\) នោះ \(4x^3-3x=\tfrac12\) គឺ \(8x^3-6x-1=0\) ដូច្នេះ \(x=\cos\tfrac\pi9\) ជាឫសនៃសមីការនេះ។ (1 ពិន្ទុ)', 'អនុវត្តន៍ក្នុងត្រីកោណមាត្រ', 'hard', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
