INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20344, 'គណនាឫសទី \(6\) នៃ \(1\) រួចបង្ហាញថាកំពូលរូបភាពរបស់វាបង្កើតបានជាឆកោននិយ័តដែលមានជ្រុងប្រវែង \(1\) (ដូចក្នុងរូប) ហើយផលបូកនៃឫសទាំងអស់ស្មើសូន្យ។', 'g12sc-3e692793fe.svg', '[]', 0, NULL, 5, 'writing', 'រូបមន្ត ៖ \(w_k=\cos\tfrac{k\pi}3+i\sin\tfrac{k\pi}3\) ដែល \(k=0,\dots,5\) (1 ពិន្ទុ)
ឫស ៖ \(1,\ \tfrac12+\tfrac{\sqrt3}2i,\ -\tfrac12+\tfrac{\sqrt3}2i,\ -1,\ -\tfrac12-\tfrac{\sqrt3}2i,\ \tfrac12-\tfrac{\sqrt3}2i\) (1 ពិន្ទុ)
ជ្រុង ៖ \(w_1-w_0=-\tfrac12+\tfrac{\sqrt3}2i\) ហើយ \(|w_1-w_0|=\sqrt{\tfrac14+\tfrac34}=1\) (1 ពិន្ទុ)
ជ្រុងផ្សេងទៀត ៖ \(w_{k+1}-w_k=(\cos\tfrac\pi3+i\sin\tfrac\pi3)^k(w_1-w_0)\) មានម៉ូឌុល \(1\) ដូចគ្នា ដូច្នេះជ្រុងទាំងប្រាំមួយស្មើ \(1\) ហើយមុំស្មើគ្នា គឺឆកោននិយ័ត (1 ពិន្ទុ)
ផលបូក ៖ \(w_0+w_3=0,\ w_1+w_4=0,\ w_2+w_5=0\) (ឫសចំណុចឆ្លុះតាមគល់) ដូច្នេះ \(\sum w_k=0\)។ (1 ពិន្ទុ)', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'hard', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20345, 'គេឱ្យ \(z=\cos\dfrac\pi6+i\sin\dfrac\pi6\)។ ក. កំណត់អាគុយម៉ង់ និងម៉ូឌុលនៃ \(z^k\) ចំពោះ \(k=1,2,\dots,7\) ។ ខ. កំណត់តម្លៃនៃ \(S=1+z+z^2+\dots+z^{11}\)។ គ. ពន្យល់ដោយធរណីមាត្រថាហេតុអ្វី \(S=0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ម៉ូឌុល និងអាគុយម៉ង់ ៖ \(z^k=\cos\tfrac{k\pi}6+i\sin\tfrac{k\pi}6\) ដូច្នេះ \(|z^k|=1\) និង \(\arg z^k=\tfrac{k\pi}6\) (ពិនិត្យ \(z^7\) ៖ \(\tfrac{7\pi}{6}\)) (1 ពិន្ទុ)
ផលបូកស្វ៊ីតធរណីមាត្រ ៖ \(S=\dfrac{z^{12}-1}{z-1}\) ដោយ \(z\ne1\) (1 ពិន្ទុ)
គណនា \(z^{12}=\cos2\pi+i\sin2\pi=1\) ដូច្នេះ \(S=\dfrac{1-1}{z-1}=0\) (1 ពិន្ទុ)
ធរណីមាត្រ ៖ ចំណុចរូបភាពនៃ \(1,z,\dots,z^{11}\) ជាកំពូលនៃពហុកោណនិយ័ត ១២ ជ្រុងលើរង្វង់ត្រីកោណមាត្រ (1 ពិន្ទុ)
ចំណុចនីមួយៗមានចំណុចផ្ទុយតាមគល់ \(z^{k+6}=-z^k\) ដូច្នេះវ៉ិចទ័រលុបគ្នាជាគូ ហើយផលបូក \(S=0\)។ (1 ពិន្ទុ)', 'អនុវត្តន៍ក្នុងត្រីកោណមាត្រ', 'hard', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-a32d9ef2fa.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20346, 'កង់ទេសចរណ៍កាំ \(10\ \text{m}\) មាន ១២ កាប៊ីនស្ថិតស្មើគ្នា ដែលកាប៊ីនលេខ \(k\) ស្ថិតត្រង់ \(w_k=10\left(\cos\tfrac{k\pi}6+i\sin\tfrac{k\pi}6\right)\) ដូចក្នុងរូប។ ក. រកទីតាំងកាប៊ីនលេខ \(4\)។ ខ. គណនាចម្ងាយរវាងកាប៊ីនជាប់គ្នា \(w_0\) និង \(w_1\)។', 'g12sc-a32d9ef2fa.svg', '[]', 0, NULL, 5, 'writing', 'កាប៊ីនលេខ \(4\) ៖ \(w_4=10\left(\cos\tfrac{2\pi}3+i\sin\tfrac{2\pi}3\right)=-5+5\sqrt3\,i\) (1 ពិន្ទុ)
ចម្ងាយ ៖ \(w_1-w_0=10\left(\tfrac{\sqrt3}2+\tfrac12i\right)-10=\left(5\sqrt3-10\right)+5i\) (1 ពិន្ទុ)
ម៉ូឌុល ៖ \(|w_1-w_0|^2=(5\sqrt3-10)^2+25=75-100\sqrt3+100+25=200-100\sqrt3\) (1 ពិន្ទុ)
ដូច្នេះ \(|w_1-w_0|=10\sqrt{2-\sqrt3}\) ហើយ \(\sqrt{2-\sqrt3}=\tfrac{\sqrt6-\sqrt2}2\) គឺ \(=5(\sqrt6-\sqrt2)\) (1 ពិន្ទុ)
តម្លៃប្រហែល ៖ \(5(2{,}449-1{,}414)\approx5{,}18\ \text{m}\) (ត្រូវនឹងជ្រុងពហុកោណនិយ័ត ១២ ជ្រុងកាំ \(10\))។ (1 ពិន្ទុ)', 'ឫសទី n នៃចំនួនកុំផ្លិច', 'pisa', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-afb5b61218.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20347, 'ស្ថានីយ៍ទូរគមនាគមន៍បួនត្រូវដាក់ស្មើគ្នាលើរង្វង់កាំ \(6\ \text{km}\) ជុំវិញប៉មមួយ ដោយស្ថានីយ៍ទី ១ នៅត្រង់ \(6\) (ឫសទី \(4\) នៃ \(1\,296\)) ដូចក្នុងរូប។ ក. រកទីតាំងស្ថានីយ៍ទាំងបួន។ ខ. គណនាចម្ងាយរវាងស្ថានីយ៍ជាប់គ្នា និងរវាងស្ថានីយ៍ឆ្លងកាត់ប៉ម។', 'g12sc-afb5b61218.svg', '[]', 0, NULL, 5, 'writing', 'រូបមន្តឫស ៖ \(1\,296=1\,296(\cos0+i\sin0)\) ដូច្នេះ \(w_k=6\left(\cos\tfrac{k\pi}2+i\sin\tfrac{k\pi}2\right)\) (1 ពិន្ទុ)
ទីតាំង ៖ \(w_0=6,\ w_1=6i,\ w_2=-6,\ w_3=-6i\) (1 ពិន្ទុ)
ស្ថានីយ៍ជាប់គ្នា ៖ \(|w_1-w_0|=|-6+6i|=6\sqrt2\approx8{,}49\ \text{km}\) (1 ពិន្ទុ)
ស្ថានីយ៍ឆ្លងកាត់ប៉ម ៖ \(|w_2-w_0|=|-12|=12\ \text{km}\) (អង្កត់ផ្ចិត) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \((6\sqrt2)^2+(6\sqrt2)^2=144=12^2\) ស្របតាមទ្រឹស្តីបទពីតាគ័រ ដូច្នេះស្ថានីយ៍បង្កើតបានជាការ៉េ។ (1 ពិន្ទុ)', 'ដោះស្រាយសមីការដោយប្រើឫសទី n', 'pisa', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20348, 'ដំណាក់កាលតម្រងមួយមានការឆ្លើយតប \(G=\sqrt2\left(\cos\dfrac\pi{12}+i\sin\dfrac\pi{12}\right)\) ។ ដំណាក់កាលដូចគ្នា ៦ តភ្ជាប់គ្នា។ ក. គណនាការឆ្លើយតបសរុប \(G^6\) ជាទម្រង់ត្រីកោណមាត្រ។ ខ. សរសេរជាទម្រង់ \(a+bi\) ហើយបញ្ជាក់អំព្លីទុត និងផាស។ គ. ផ្ទៀងផ្ទាត់ជាមួយ \(G^2\) រួចលើកស្វ័យគុណទី \(3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'រូបមន្តដឺម័រ ៖ \(G^6=(\sqrt2)^6\left(\cos\tfrac{6\pi}{12}+i\sin\tfrac{6\pi}{12}\right)\) (1 ពិន្ទុ)
គណនា ៖ \((\sqrt2)^6=8\) ហើយ \(\tfrac{6\pi}{12}=\tfrac\pi2\) ដូច្នេះ \(G^6=8\left(\cos\tfrac\pi2+i\sin\tfrac\pi2\right)\) (1 ពិន្ទុ)
ទម្រង់ពីជគណិត ៖ \(G^6=8i\) (1 ពិន្ទុ)
អំព្លីទុត \(|G^6|=8\) ហើយផាស \(\tfrac\pi2=90^\circ\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(G^2=2\left(\cos\tfrac\pi6+i\sin\tfrac\pi6\right)=\sqrt3+i\) ហើយ \((G^2)^3=(\sqrt3+i)^3=8i\) (ព្រោះ \(2^3\left(\cos\tfrac\pi2+i\sin\tfrac\pi2\right)\)) ស្របគ្នា។ (1 ពិន្ទុ)', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'pisa', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20349, 'ចុងអង់តែនប្រវែង \(2\ \text{m}\) ចាប់ផ្ដើមតាមអ័ក្សពិត \(z_0=2\) ហើយវិលច្រាសទ្រនិចនាឡិការៀងរាល់ម៉ោងបានម៉ុំ \(\dfrac\pi6\) ជុំវិញគល់ \(O\)។ ក្រោយ \(n\) ម៉ោង ទីតាំងគឺ \(z_n=2\left(\cos\tfrac\pi6+i\sin\tfrac\pi6\right)^n\)។ ក. រក \(z_3\) និង \(z_4\)។ ខ. ក្រោយប៉ុន្មានម៉ោងទើបចុងអង់តែនត្រលប់ទីតាំងដើមជាលើកដំបូង ? គ. តើក្នុង \(12\) ម៉ោង ចុងអង់តែនឆ្លងកាត់ឫសទី \(12\) នៃអ្វី ?', NULL, '[]', 0, NULL, 5, 'writing', 'រូបមន្តដឺម័រ ៖ \(z_n=2\left(\cos\tfrac{n\pi}6+i\sin\tfrac{n\pi}6\right)\) (1 ពិន្ទុ)
\(z_3=2\left(\cos\tfrac\pi2+i\sin\tfrac\pi2\right)=2i\) និង \(z_4=2\left(\cos\tfrac{2\pi}3+i\sin\tfrac{2\pi}3\right)=-1+\sqrt3\,i\) (1 ពិន្ទុ)
ត្រលប់ដើម ៖ \(z_n=2\) ពេល \(\tfrac{n\pi}6=2\pi\) ដូច្នេះ \(n=12\) ម៉ោង (1 ពិន្ទុ)
គ្រប់ \(n\) ៖ \(z_n^{12}=2^{12}(\cos2n\pi+i\sin2n\pi)=2^{12}=4\,096\) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ទីតាំងទាំង ១២ ជាឫសទី \(12\) នៃ \(4\,096\) ហើយស្ថិតលើរង្វង់កាំ \(2\) ជាកំពូលនៃពហុកោណនិយ័ត ១២ ជ្រុង។ (1 ពិន្ទុ)', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'pisa', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20350, 'ជណ្ដើរវង់មួយមានជំហាន ដែលជំហាននីមួយៗបង្វិលទិសច្រាសទ្រនិចនាឡិកាម៉ុំ \(\dfrac\pi4\) ហើយពង្រីកចម្ងាយពីគល់ \(O\) ឱ្យធំជា \(\sqrt2\) ដង។ ចំណុចជំហានទី \(n\) តាងដោយ \(z_n=(1+i)^n\) (ជំហានទី ០ ជា \(z_0=1\))។ ក. បង្ហាញថា \(1+i\) បង្វិល \(\tfrac\pi4\) និងពង្រីក \(\sqrt2\)។ ខ. រក \(z_4\) និង \(z_8\)។ គ. រកជំហានតូចបំផុតដែលចម្ងាយពី \(O\) លើស \(100\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទម្រង់ត្រីកោណមាត្រ ៖ \(1+i=\sqrt2\left(\cos\tfrac\pi4+i\sin\tfrac\pi4\right)\) ដូច្នេះគុណនឹង \(1+i\) បង្វិល \(\tfrac\pi4\) ហើយពង្រីក \(\sqrt2\) ដង (1 ពិន្ទុ)
រូបមន្តដឺម័រ ៖ \(z_n=(\sqrt2)^n\left(\cos\tfrac{n\pi}4+i\sin\tfrac{n\pi}4\right)\) (1 ពិន្ទុ)
\(z_4=4(\cos\pi+i\sin\pi)=-4\) ហើយ \(z_8=16(\cos2\pi+i\sin2\pi)=16\) (1 ពិន្ទុ)
ចម្ងាយ \(|z_n|=2^{n/2}\) ត្រូវការ \(2^{n/2}>100\) គឺ \(n>2\log_2\,100\approx13{,}29\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(n=13\) ឱ្យ \(2^{6{,}5}\approx90{,}5<100\) ហើយ \(n=14\) ឱ្យ \(2^7=128>100\) ដូច្នេះជំហានតូចបំផុតគឺ \(n=14\)។ (1 ពិន្ទុ)', 'ស្វ័យគុណទី n នៃចំនួនកុំផ្លិច', 'pisa', 0, '12SC', 'ស្វ័យគុណទី n និងឫសទី n នៃចំនួនកុំផ្លិច', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
